const MAX_SOUND_SAMPLES: usize = 16 << 20;
// in wave_resources:
let mut decoded: HashMap<(u16, u16), std::rc::Rc<[f32]>> = HashMap::new();
let mut total = 0usize;
// per WAVESFXn entry:
let pcm = match decoded.get(&(type_id, res_id)) {
    Some(p) => p.clone(),
    None => {
        let p: std::rc::Rc<[f32]> = decode_wav(wav)?.into();
        total = total.saturating_add(p.len());
        if total > MAX_SOUND_SAMPLES {
            return Err(AssetError::Format("NE sound resources too large".into()));
        }
        decoded.insert((type_id, res_id), p.clone());
        p
    }
};
